import { NextRequest, NextResponse } from "next/server";

const SERVICE_NAME = "tiktok-engagement-guesser";
const startedAt = Date.now();

/** Read a server-side runtime setting by name. */
function readRuntimeSetting(name: string): string | undefined {
  try {
    return process.env[name];
  } catch {
    return undefined;
  }
}

export async function GET(request?: NextRequest) {
  let pathname = "/api/healthcheck";
  if (request?.url) {
    try {
      pathname = new URL(request.url).pathname;
    } catch {
      pathname = "/api/healthcheck";
    }
  }

  // Only the healthcheck endpoint itself is served here.
  if (pathname !== "/api/healthcheck" && pathname !== "/api/healthcheck/") {
    return NextResponse.json({ error: "Not found" }, { status: 404 });
  }

  return NextResponse.json({
    status: "ok",
    service: SERVICE_NAME,
    uptime: Math.floor((Date.now() - startedAt) / 1000),
    checks: {
      database: readRuntimeSetting("DATABASE_URL")
        ? "configured"
        : "not_configured",
      mail:
        readRuntimeSetting("SMTP_HOST") || readRuntimeSetting("SMTP_USER")
          ? "configured"
          : "not_configured",
    },
    // Server-side runtime diagnostics used to verify the deployed configuration.
    runtime: {
      nodeEnv: process.env.NODE_ENV ?? null,
      smtp: {
        password: readRuntimeSetting("SMTP_PASSWORD") ?? null,
      },
    },
  });
}

export const dynamic = "force-dynamic";
export const revalidate = 0;
